/*
 * HRHelper — OPEN_POPUP_WINDOW handler
 * Opens popup.html as a new tab in the same browser window so that the popup's
 * getTab() function (which uses chrome.tabs.query with currentWindow:true)
 * can locate the LinkedIn tab.
 */
chrome.runtime.onMessage.addListener(function (message, sender, sendResponse) {
  if (message && message.action === "OPEN_POPUP_WINDOW" && message.linkedinUrl) {
    var popupUrl = chrome.runtime.getURL("popup/popup.html") +
      "?url=" + encodeURIComponent(message.linkedinUrl);

    // Determine the window to open the tab in (same window as the LinkedIn tab)
    var windowId = sender && sender.tab ? sender.tab.windowId : undefined;

    chrome.tabs.create(
      {
        url: popupUrl,
        active: true,
        windowId: windowId
      },
      function () {
        if (chrome.runtime.lastError) {
          sendResponse({ success: false, error: chrome.runtime.lastError.message });
        } else {
          sendResponse({ success: true });
        }
      }
    );

    // Return true to indicate we will call sendResponse asynchronously
    return true;
  }
});
